import React, { forwardRef, type ForwardedRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { SvgIconProps } from "./svg-icon.types";
import { SvgIconClasses, StyledSvgIcon } from "./svg-icon.styles";

const SvgIcon = forwardRef<SVGElement, SvgIconProps>(
  (
    {
      className,
      children,
      title,
      height,
      width,
      fontSize,
      desc: description,
      color,
      style,
      ...props
    },
    ref: ForwardedRef<SVGElement>,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(SvgIconClasses.root, className);
    const ariaHidden = props["aria-labelledby"] ? undefined : "true";
    const hasSvgAsChild = React.isValidElement(children) && children.type === "svg";
    const child = !hasSvgAsChild ? (children as JSX.Element).type?.() : children;

    return (
      <StyledSvgIcon
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        {...child.props}
        aria-hidden={ariaHidden}
        fontSize={fontSize}
        height={fontSize ?? height}
        role={title ? "img" : undefined}
        style={{ color, ...style }}
        width={fontSize ?? width}
        {...props}
      >
        {title && <title>{title}</title>}
        {description && <desc>{description}</desc>}
        {child.props.children}
      </StyledSvgIcon>
    );
  },
);

SvgIcon.displayName = "SvgIcon";

export default SvgIcon;
